create table if not exists public.delivery_jobs (id uuid primary key default gen_random_uuid(), order_group_id uuid not null references public.order_groups(id) on delete cascade, status text not null default 'pending_assignment' check (status in ('pending_assignment','assigned','picked_up','in_transit','delivered','failed','cancelled')), customer_delivery_pin_hash text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.delivery_stops (id uuid primary key default gen_random_uuid(), delivery_job_id uuid not null references public.delivery_jobs(id) on delete cascade, order_id uuid references public.orders(id), stop_type text not null check (stop_type in ('pickup','dropoff')), sequence integer not null check (sequence > 0), address jsonb not null, status text not null default 'pending' check (status in ('pending','arrived','completed','failed')), created_at timestamptz not null default now());
create table if not exists public.delivery_assignments (id uuid primary key default gen_random_uuid(), delivery_job_id uuid not null references public.delivery_jobs(id) on delete cascade, rider_id uuid not null references public.riders(id), status text not null default 'offered' check (status in ('offered','accepted','rejected','completed','cancelled')), offered_at timestamptz not null default now(), responded_at timestamptz);
create table if not exists public.delivery_proofs (id uuid primary key default gen_random_uuid(), delivery_job_id uuid not null references public.delivery_jobs(id) on delete cascade, image_path text, note text not null default '', delivered_at timestamptz not null default now());
create table if not exists public.support_tickets (id uuid primary key default gen_random_uuid(), customer_id uuid references public.profiles(id), subject text not null, body text not null, status text not null default 'open' check (status in ('open','pending','resolved','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid, action text not null, entity text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.notification_outbox (id uuid primary key default gen_random_uuid(), recipient_id uuid, channel text not null check (channel in ('email','sms','whatsapp','push')), payload jsonb not null, status text not null default 'queued' check (status in ('queued','sent','failed')), attempts integer not null default 0, next_attempt_at timestamptz not null default now(), created_at timestamptz not null default now());
create trigger set_updated before update on public.delivery_jobs for each row execute function public.set_updated_at();
create trigger set_updated before update on public.support_tickets for each row execute function public.set_updated_at();
